/* @lc app=leetcode id=3072 lang=kotlin */ class Solution { fun bu(t: IntArray, i: Int) = generateSequence(i) { it + (it and -it) }.takeWhile { it < t.size }.forEach { t[it]++ } fun bq(t: IntArray, i: Int): Int = generateSequence(i) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { t[it] } fun resultArray(nums: IntArray): IntArray = nums.toSet().sorted().let { co -> IntArray(co.size + 1).let { t1 -> IntArray(co.size + 1).let { t2 -> ArrayList<Int>().let { a1 -> ArrayList<Int>().let { a2 -> nums.indices.forEach { i -> (co.binarySearch(nums[i]) + 1).let { r -> (if (i == 0) true else if (i == 1) false else (a1.size - bq(t1, r)).let { g1 -> (a2.size - bq(t2, r)).let { g2 -> g1 > g2 || g1 == g2 && a1.size <= a2.size } }).let { first -> if (first) a1.add(nums[i]).also { bu(t1, r) } else a2.add(nums[i]).also { bu(t2, r) } } } }.let { (a1 + a2).toIntArray() } } } } } } }